{
  "headline": "Spironolactone is not on FDA's shortage list as of 2026-10-21; internal supply at Corvale East is 8.5 days on hand for 100 mg tablets",
  "headline_cites": ["D6", "D1"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows spironolactone is not listed as of 2026-10-21.",
      "cites": ["D6"]
    },
    {
      "text": "Corvale East holds 106 tablets of spironolactone 100 mg with a daily use of 12.5 tablets, giving 8.5 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 375 tablets of the same 100 mg presentation with a daily use of 13.9 tablets, giving 27 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Both sites' 100 mg tablets carry NDC 70518372103 labeled by REMEDYREPACK INC. and the SPL set ID 7646ca22-710e-4a5c-9613-b829e2f9d5ce.",
      "cites": ["E1", "E3"]
    },
    {
      "text": "The label for that SPL set names OXFORD PHARMS as the manufacturing plant.",
      "cites": ["E6"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 69 tablets of 100 mg from Corvale General to Corvale East, which would raise Corvale East to 14 days on hand while Corvale General retains two weeks of supply.",
      "cites": ["D7"]
    }
  ]
}
